const char* prompts[D] = {"translate English to German: The keys are on the table.","translate English to German: The cat is on the mat.","translate English to German: The door is open.","translate English to French: The door is open.","translate English to French: The book is new.","summarize: The small observatory was flooded after a storm.","summarize: A careful engineer repaired the bridge before sunset.","summarize: The museum opened a new exhibit about ancient tools.","question: What color is the sky? answer:","question: Who wrote Hamlet? answer:","question: What is two plus two? answer:","question: Where do fish live? answer:","classify sentiment: I loved the careful and helpful explanation.","classify sentiment: The service was slow and disappointing.","complete: The keys to the cabinet","complete: The bright star in the night","translate English to German: The child reads a book.","translate English to French: The child reads a book.","translate English to Spanish: The house is large.","translate English to Spanish: The river is cold.","summarize: The researchers measured the signal and published the result.","summarize: A train arrived late because of heavy snow.","summarize: The gardener planted seeds beside the old wall.","summarize: The committee approved the proposal after discussion.","question: What gas do humans breathe? answer:","question: How many days are in a week? answer:","question: What planet do we live on? answer:","question: What is the opposite of hot? answer:","classify sentiment: The explanation was clear and useful.","classify sentiment: I disliked the confusing instructions.","complete: The old map beside the river","complete: The engineer designed a small"};
void replay(int sid,string prefix,double p,map<string,double>& out){ const auto&s=states[sid]; if(s.depth==H){out[prefix]+=p;return;} double z=65535.0; for(int i=0;i<8;++i) if(s.mass[i]){double pi=p*s.mass[i]/z; if(s.depth==H-1) out[prefix+to_string(s.token[i])+" "]+=pi; else {int nx=-1;for(int j=0;j<s.edge_count;++j)if(s.edge[j].token==s.token[i])nx=s.edge[j].next;if(nx>=0)replay(nx,prefix+to_string(s.token[i])+" ",pi,out);}} out[prefix+"OTHER"]+=p*s.other/z; }
void sample(int pid,unsigned seed){mt19937 g(seed);int sid=roots[pid];cout<<"prompt="<<pid<<" text="<<prompts[pid]<<"\npath=";for(int step=0;step<H;++step){const auto&s=states[sid];uniform_int_distribution<int> u(1,65535);int draw=u(g),chosen=-1;for(int i=0;i<2;++i){if(draw<=s.mass[i]){chosen=i;break;}draw-=s.mass[i];}if(chosen<0){cout<<"OTHER\n";return;}cout<<s.token[chosen]<<" ";if(step==H-1){cout<<"\n";return;}int nx=-1;for(int j=0;j<s.edge_count;++j)if(s.edge[j].token==s.token[chosen])nx=s.edge[j].next;if(nx<0){cout<<"OTHER\n";return;}sid=nx;}cout<<"\n";}
int main(int argc,char**argv){cout<<"PRSL-STACK-1-CXX23\n"<<"states="<<N<<" prompts="<<D<<" horizon="<<H<<"\n";if(argc==4&&string(argv[1])=="--sample"){sample(stoi(argv[2]),stoul(argv[3]));return 0;}cout<<fixed<<setprecision(12);for(int d=0;d<D;++d){map<string,double> law;replay(roots[d],"",1.0,law);double mass=0;for(auto&x:law)mass+=x.second;cout<<"prompt="<<d<<" outcomes="<<law.size()<<" mass="<<mass<<"\n";}}
